function calculate() {
            const volume = parseFloat(document.getElementById('volume').value) || 0;
            const hours = parseFloat(document.getElementById('hours').value) || 0;
            const minutes = parseFloat(document.getElementById('minutes').value) || 0;
            const dropFactor = parseFloat(document.getElementById('drop-factor').value) || 60;
            const tubing = parseFloat(document.getElementById('tubing').value) || 1;

            const totalMinutes = (hours * 60) + minutes;
            if (totalMinutes === 0 || volume === 0) return;

            const totalHours = totalMinutes / 60;
            const mlHr = Math.round(volume / totalHours);
            const gttMin = Math.round((volume * dropFactor * tubing) / totalMinutes);

            document.getElementById('ml-hr').textContent = mlHr;
            document.getElementById('gtt-min').textContent = gttMin;

            document.getElementById('ref-30').textContent = Math.round((30 / totalMinutes) * mlHr) || '--';
            document.getElementById('ref-60').textContent = Math.round((60 / totalMinutes) * mlHr) || '--';
            document.getElementById('ref-120').textContent = Math.round((120 / totalMinutes) * mlHr) || '--';
            document.getElementById('ref-240').textContent = Math.round((240 / totalMinutes) * mlHr) || '--';
        }

        calculate();
